    constructor(C _c) {
        c = _c;
    }

    // We test the invariant: setSlopes should revert iff kink == 0 or kink >= 1e27.
    // We can't directly read stored slopeData (it's internal), so we check only the revert behavior
    // of calling setSlopes. The rule: for any input slopes, the call reverts exactly when
