contract InvMutTest {
    C c;

    event DummySetSlopes(address indexed asset);

    constructor(C _c) { c = _c; }

    // We test two properties in one assert: when kink is valid, setSlopes does not revert and the stored slopes match inputs;
    // when kink is invalid (==0 or >=1e27) the call must revert. We observe stored slopes via calling rate after initializing storage
    // indirectly: since slopeData is not publicly exposed, we rely on the fact that setSlopes emits SetSlopes event and does not revert
    // for valid inputs. To make an observable state read, we call setLimits (which is public) guarded by same access check; however Access
    // will revert unless accessControl is setup. To avoid access control, we will attempt setSlopes and detect revert. The general rule asserted:
    // (validKink => not reverted) && (invalidKink => reverted)

    // Note: as per constraints we must end with a single assert expressing a general rule over inputs and observed revert flag.

    // We need to supply an asset and slope params. The function is payable only for interface; not sending Ether here.
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        require(asset != address(0)); // ensure asset is a sensible address for event indexing

        // Build calldata by calling setSlopes via low-level call to capture revert without needing access permissions.
        // Prepare ABI-encoded data for setSlopes(address,(uint256,uint256,uint256))
        bytes memory data = abi.encodeWithSelector(c.setSlopes.selector, asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1}));

        bool reverted;
        // Call via address(c).call to bypass Access check and observe revert status. This still targets C implementation; we only observe if it reverted.
        // According to the contract, setSlopes will revert on invalid kink; otherwise it will attempt to checkAccess which may revert if access not granted.
        // However the property we assert is solely about the kink validation: if kink==0 or kink>=1e27 the implementation MUST revert at least due to InvalidKink,
        // so low-level call should revert. If kink is in (0,1e27) then setSlopes should NOT immediately revert with InvalidKink; it may still revert later due to access control,
        // but the rule we assert will treat absence of InvalidKink revert as success. To detect InvalidKink specifically we inspect returned returndata for selector of that error.

        (bool ok, bytes memory ret) = address(c).call(data);
        if (!ok) {
            // try to decode custom error InvalidKink() signature: keccak256("InvalidKink()") first 4 bytes
            bytes4 invalidKinkSig = bytes4(keccak256("InvalidKink()"));
            if (ret.length >= 4) {
                bytes4 sig;
                assembly { sig := mload(add(ret, 32)) }
                // if matches InvalidKink signature then we mark as kinkRevert
                if (sig == invalidKinkSig) {
                    reverted = true;
                } else {
                    // some other revert (e.g., AccessDenied). Mark as not an InvalidKink revert
                    reverted = false;
                }
            } else {
                reverted = false;
            }
        } else {
            reverted = false;
        }

        // Our general rule: (kink == 0 || kink >= 1e27) implies the call must revert with InvalidKink; otherwise it must NOT revert with InvalidKink.
        // Expressed: (isInvalidKink == reverted)
        bool isInvalidKink = (kink == 0 || kink >= 1e27);
        assert(isInvalidKink == reverted);
    }

    // fallback/receive not needed beyond defaults
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test that calling setSlopes on c reverts with InvalidKink if and only if kink is 0 or >= 1e27.
    // The call must be a top-level call to c.setSlopes; we use try/catch on the external call to observe whether it reverted
    // and inspect the returned error selector if present to detect InvalidKink().
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        require(asset != address(0));

        bool revertedWithInvalidKink = false;

        // Top-level state-changing call as required by the checker
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            // call succeeded (did not revert)
            revertedWithInvalidKink = false;
        } catch (bytes memory reason) {
            // call reverted; inspect reason for InvalidKink() selector
            if (reason.length >= 4) {
                bytes4 sig;
                assembly { sig := mload(add(reason, 32)) }
                if (sig == bytes4(keccak256("InvalidKink()"))) {
                    revertedWithInvalidKink = true;
                } else {
                    revertedWithInvalidKink = false;
                }
            } else {
                revertedWithInvalidKink = false;
            }
        }

        bool isInvalidKink = (kink == 0 || kink >= 1e27);
        // General rule: setSlopes reverts with InvalidKink iff kink is invalid
        assert(isInvalidKink == revertedWithInvalidKink);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Test that setLimits(_max, _min, _rate) updates VaultAdapterStorage so that
    // the public getters (accessed via storage-reading public functions) reflect the new values.
    // We call setLimits as a top-level state-changing call and then read back via view getters.
    // The rule: after a successful setLimits call, the stored .maxMultiplier, .minMultiplier and .rate
    // as observed through the public storage accessors must equal the inputs.
    function run(uint256 _maxMultiplier, uint256 _minMultiplier, uint256 _rate) public payable {
        // No precondition on values; call may revert due to access control — we capture that.
        bool reverted = false;

        // Top-level state-changing call required by the checker
        try c.setLimits(_maxMultiplier, _minMultiplier, _rate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read back via public view functions (these are allowed). We can only observe through c's public surface.
        // c does not expose direct getters for these storage slots; however, the contract emits SetLimits event but events are not readable here.
        // The only publicly exposed way to observe is to call c.rate with some parameters which may use the stored $.rate and multipliers
        // but that's indirect and can have side-effects; instead, ERC requires we only use public/external views — there are no direct getters.
        // Therefore we use a conservative observable: if setLimits succeeded (not reverted) then calling setLimits again with the same values
        // should not revert (idempotence for same inputs) and must succeed. We encode the rule as: if first call did not revert, a second identical call also does not revert.

        bool secondReverted = false;
        try c.setLimits(_maxMultiplier, _minMultiplier, _rate) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: success of the first setLimits implies success of the second identical setLimits.
        assert(reverted == false ? secondReverted == false : true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test idempotence of setSlopes for valid kink values when the call succeeds:
    // If the first setSlopes(_asset, _slopes) call (from this contract) succeeds, then
    // calling setSlopes again with the identical params must also succeed.
    // To keep things simple and observable, we require a valid kink in (0, 1e27).
    function run(address _asset, uint256 _kink, uint256 _slope0, uint256 _slope1) public payable {
        // Precondition: kink must be in the valid range (0, 1e27) as per contract requirements.
        require(_kink > 0 && _kink < 1e27, "kink out of valid range");

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({kink: _kink, slope0: _slope0, slope1: _slope1});

        bool firstReverted;
        try c.setSlopes(_asset, slopes) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.setSlopes(_asset, slopes) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: if the first call succeeded (did not revert), the second identical call must also succeed.
        assert(firstReverted == false ? secondReverted == false : true);
    }

    receive() external payable {}
